import{_ as t,o as l,c as p,ai as k}from"./chunks/framework.Ai2o9gNv.js";const e="/assets/screenshot-home.CPUTQXB-.webp",i="/assets/screenshot-same-drag.BTwZaLQl.webp",a="/assets/screenshot-diff-drag.CH9cu1Tn.webp",n="/assets/screenshot-direct-drag.DbCAnGMs.webp",h="/assets/screenshot-jitter.CmLYQiRd.webp",m=JSON.parse("{\"title\":\"GridDragSort — HarmonyOS 网格拖拽场景\",\"description\":\"\",\"frontmatter\":{},\"headers\":[],\"relativePath\":\"HarmonyOS 最佳实践/19-GridDragSort — HarmonyOS 网格拖拽场景/19-GridDragSort — HarmonyOS 网格拖拽场景.md\",\"filePath\":\"HarmonyOS 最佳实践/19-GridDragSort — HarmonyOS 网格拖拽场景/19-GridDragSort — HarmonyOS 网格拖拽场景.md\",\"lastUpdated\":1778632377000,\"__rawMarkdown\":\"# GridDragSort — HarmonyOS 网格拖拽场景\\n\\n> 项目地址：https://gitcode.com/harmonyos_samples/grid-drag-sort\\n> 技术栈：HarmonyOS / ArkTS / ArkUI\\n\\n## 项目简介\\n\\n在移动应用开发中，网格布局（Grid）是一种常见且高效的界面组织方式，广泛应用于相册、设备管理、应用桌面等场景。而网格元素的拖拽排序功能，则为用户提供了直观、灵活的内容组织能力，是提升交互体验的重要手段。\\n\\n**GridDragSort** 是 HarmonyOS 官方示例项目，专注于展示基于 `Grid` 组件的四大网格拖拽排序场景：\\n\\n- **相同大小元素长按拖拽**：九宫格等分布局，长按后拖拽交换排序\\n- **不同大小元素长按拖拽**：大小卡片混合布局，支持跨尺寸拖拽交换\\n- **直接拖拽（无需长按）**：轻触即可拖拽，适合高频排序场景\\n- **抖动动画编辑模式**：长按进入编辑模式，元素抖动并显示删除按钮\\n\\n本项目通过 `Grid` 容器组件、组合手势（GestureGroup）和显式动画（animateTo）的有机结合，实现了流畅自然的拖拽交互体验。\\n\\n![首页截图](assets/screenshot-home.webp)\\n\\n_上图展示了应用首页，四个按钮分别对应四大拖拽排序场景。_\\n\\n## 功能概览\\n\\n| 场景 | 核心组件 | 关键技术 |\\n|------|---------|---------|\\n| 相同大小元素拖拽 | `Grid` + `GridItem` | `editMode` + `supportAnimation` |\\n| 不同大小元素拖拽 | `Grid` + `GestureGroup` | `LongPressGesture` + `PanGesture` |\\n| 直接拖拽 | `Grid` + `PanGesture` | 单手势直接拖拽 |\\n| 抖动动画 | `Grid` + `animateTo` | 循环动画 + 编辑模式 |\\n\\n## 工程结构\\n\\n```text\\nentry/src/main/ets\\n├── entryability\\n│   └── EntryAbility.ets              // 程序入口\\n├── entrybackupability\\n│   └── EntryBackupAbility.ets        // 备份能力\\n└── pages\\n    ├── Index.ets                     // 首页（导航入口）\\n    ├── SameItemDrag.ets              // 相同大小元素拖拽场景\\n    ├── DifferentItemDrag.ets         // 不同大小元素拖拽场景\\n    ├── DirectDragItem.ets            // 直接拖拽场景\\n    └── JitterAnimation.ets           // 抖动动画场景\\n```\\n\\n## 核心实现解析\\n\\n### 场景一：相同大小元素长按拖拽（SameItemDrag.ets）\\n\\n相同大小元素拖拽场景模拟了相册九宫格编辑功能。用户长按任意图片后，可以拖拽与其他图片交换位置，拖拽过程中其他图片会自动调整位置。\\n\\n![相同大小元素拖拽](assets/screenshot-same-drag.webp)\\n\\n_上图展示了相同大小元素的九宫格布局，包含用户信息、文字描述和 3x3 图片网格。_\\n\\n**核心代码：**\\n\\n```typescript\\nGrid() {\\n  ForEach(this.numbers, (item: number) => {\\n    GridItem() {\\n      Image($r(`app.media.image${item}`))\\n        .width('100%')\\n        .height(this.curBp === 'md' ? 131 : 105)\\n        .draggable(false)\\n        .animation({ curve: Curve.Sharp, duration: 300 })\\n    }\\n  }, (item: number) => item.toString())\\n}\\n.width(this.curBp === 'md' ? '66%' : '100%')\\n.scrollBar(BarState.Off)\\n.columnsTemplate('1fr 1fr 1fr')\\n.columnsGap(this.curBp === 'md' ? 6 : 4)\\n.rowsGap(this.curBp === 'md' ? 6 : 4)\\n\\n// 启用编辑模式和动画支持\\n.editMode(true)\\n.supportAnimation(true)\\n\\n// 拖拽开始回调\\n.onItemDragStart((_, itemIndex: number) => {\\n  this.imageNum = this.numbers[itemIndex];\\n  return this.pixelMapBuilder();\\n})\\n\\n// 拖拽放置回调\\n.onItemDrop((_, itemIndex: number, insertIndex: number, isSuccess: boolean) => {\\n  if (!isSuccess || insertIndex >= this.numbers.length) {\\n    return;\\n  }\\n  this.changeIndex(itemIndex, insertIndex);\\n})\\n```\\n\\n**数据交换方法：**\\n\\n```typescript\\nchangeIndex(index1: number, index2: number) {\\n  let tmp = this.numbers.splice(index1, 1);\\n  this.numbers.splice(index2, 0, tmp[0])\\n}\\n```\\n\\n**技术要点：**\\n\\n1. **`editMode(true)`**：启用 Grid 的编辑模式，允许元素拖拽\\n2. **`supportAnimation(true)`**：启用拖拽动画，让元素移动更流畅\\n3. **`onItemDragStart`**：拖拽开始时构建跟随手指移动的预览组件（`pixelMapBuilder`）\\n4. **`onItemDrop`**：拖拽结束时交换数据数组中的元素位置\\n5. **`animation`**：为每个 `GridItem` 添加过渡动画，使位置变化更自然\\n\\n### 场景二：不同大小元素长按拖拽（DifferentItemDrag.ets）\\n\\n不同大小元素拖拽场景模拟了智能家居设备管理界面。网格中包含一个大尺寸卡片（占据两行）和多个小尺寸卡片，用户长按后可以拖拽交换位置，系统会自动处理大小卡片的位置计算。\\n\\n![不同大小元素拖拽](assets/screenshot-diff-drag.webp)\\n\\n_上图展示了不同大小元素的设备网格布局，左侧 Sound X 为大卡片，右侧为多个小卡片。_\\n\\n**核心代码：**\\n\\n```typescript\\nGrid() {\\n  ForEach(this.numbers, (item: number) => {\\n    GridItem() {\\n      Stack({ alignContent: Alignment.TopEnd }) {\\n        Image(this.changeImage(item))\\n          .width('100%')\\n          .borderRadius(16)\\n          .objectFit(this.curBp === 'md' ? ImageFit.Fill : ImageFit.Cover)\\n          .draggable(false)\\n          .animation({ curve: Curve.Sharp, duration: 300 })\\n      }\\n    }\\n    .rowStart(0)\\n    .rowEnd(this.getRowEnd(item))  // 大卡片占据两行\\n    .scale({ x: this.scaleItem === item ? 1.02 : 1, y: this.scaleItem === item ? 1.02 : 1 })\\n    .zIndex(this.dragItem === item ? 1 : 0)\\n    .translate(this.dragItem === item ? { x: this.offsetX, y: this.offsetY } : { x: 0, y: 0 })\\n    .gesture(\\n      GestureGroup(GestureMode.Sequence,\\n        LongPressGesture({ repeat: true })\\n          .onAction(() => {\\n            this.getUIContext().animateTo({ curve: Curve.Friction, duration: 300 }, () => {\\n              this.scaleItem = item;\\n            })\\n          })\\n          .onActionEnd(() => {\\n            this.getUIContext().animateTo({ curve: Curve.Friction, duration: 300 }, () => {\\n              this.scaleItem = -1;\\n            })\\n          }),\\n        PanGesture({ fingers: 1, direction: null, distance: 0 })\\n          .onActionStart(() => {\\n            this.dragItem = item;\\n            this.dragRefOffSetX = 0;\\n            this.dragRefOffSetY = 0;\\n          })\\n          .onActionUpdate((event: GestureEvent) => {\\n            this.offsetX = event.offsetX - this.dragRefOffSetX;\\n            this.offsetY = event.offsetY - this.dragRefOffSetY;\\n            this.getUIContext().animateTo({ \\n              curve: curves.interpolatingSpring(0, 1, 400, 38) \\n            }, () => {\\n              let index = this.numbers.indexOf(this.dragItem);\\n              // 根据偏移量判断移动方向并交换位置\\n              if (this.offsetY >= this.FIX_VP_Y / 2) {\\n                this.down(index);\\n              } else if (this.offsetY <= -this.FIX_VP_Y / 2) {\\n                this.up(index);\\n              } else if (this.offsetX >= this.FIX_VP_X / 2) {\\n                this.right(index);\\n              } else if (this.offsetX <= -this.FIX_VP_X / 2) {\\n                this.left(index);\\n              }\\n            })\\n          })\\n          .onActionEnd(() => {\\n            // 拖拽结束，重置状态\\n            this.getUIContext().animateTo({ \\n              curve: curves.interpolatingSpring(0, 1, 400, 38) \\n            }, () => {\\n              this.dragItem = -1;\\n            })\\n          })\\n      )\\n    )\\n  })\\n}\\n.columnsTemplate('1fr 1fr')\\n.editMode(true)\\n.supportAnimation(true)\\n```\\n\\n**技术要点：**\\n\\n1. **`GestureGroup(GestureMode.Sequence)`**：使用序列手势组合，先长按（`LongPressGesture`）后拖拽（`PanGesture`）\\n2. **`rowStart` / `rowEnd`**：通过设置行起始和结束位置，实现大卡片占据多行\\n3. **方向判断逻辑**：在 `onActionUpdate` 中根据偏移量判断上下左右四个方向的移动\\n4. **弹性动画**：使用 `curves.interpolatingSpring` 创建弹簧效果，让交互更有质感\\n5. **位置计算**：`FIX_VP_X` 和 `FIX_VP_Y` 定义了网格单元格的固定尺寸，用于判断移动阈值\\n\\n### 场景三：直接拖拽（DirectDragItem.ets）\\n\\n直接拖拽场景省去了长按步骤，用户手指轻触元素即可直接拖拽。这种交互方式适合需要频繁调整顺序的场景，如桌面图标整理。\\n\\n![直接拖拽](assets/screenshot-direct-drag.webp)\\n\\n_上图展示了直接拖拽场景，5 个空间设备卡片以 4 列网格排列，无需长按即可直接拖拽。_\\n\\n**核心代码：**\\n\\n```typescript\\nGrid() {\\n  ForEach(this.numbers, (item: number) => {\\n    GridItem() {\\n      Column() {\\n        Image($r(`app.media.space${item}`))\\n          .width(44)\\n          .height(44)\\n          .draggable(false)\\n        Image($r('app.media.space_bottom'))\\n          .width(16)\\n          .height(16)\\n          .draggable(false)\\n      }\\n      .width('100%')\\n      .height(73)\\n      .justifyContent(FlexAlign.Center)\\n      .borderRadius(10)\\n      .backgroundColor('#F1F3F5')\\n      .animation({ curve: Curve.Sharp, duration: 300 })\\n    }\\n    .scale({ x: this.scaleItem === item ? 1.05 : 1, y: this.scaleItem === item ? 1.05 : 1 })\\n    .zIndex(this.dragItem === item ? 1 : 0)\\n    .translate(this.dragItem === item ? { x: this.offsetX, y: this.offsetY } : { x: 0, y: 0 })\\n    .gesture(\\n      PanGesture({ fingers: 1, direction: null, distance: 0 })\\n        .onActionStart(() => {\\n          this.dragItem = item;\\n          this.dragRefOffSetX = 0;\\n          this.dragRefOffSetY = 0;\\n        })\\n        .onActionUpdate((event: GestureEvent) => {\\n          this.offsetX = event.offsetX - this.dragRefOffSetX;\\n          this.offsetY = event.offsetY - this.dragRefOffSetY;\\n          this.getUIContext().animateTo({ \\n            curve: curves.interpolatingSpring(0, 1, 400, 38) \\n          }, () => {\\n            let index = this.numbers.indexOf(this.dragItem);\\n            // 支持上下左右及四个对角线方向的移动\\n            if (this.offsetY >= this.FIX_VP_Y / 2) {\\n              this.down(index);\\n            } else if (this.offsetY <= -this.FIX_VP_Y / 2) {\\n              this.up(index);\\n            } else if (this.offsetX >= this.FIX_VP_X / 2) {\\n              this.right(index);\\n            } else if (this.offsetX <= -this.FIX_VP_X / 2) {\\n              this.left(index);\\n            } else if (this.offsetX >= this.FIX_VP_X / 2 && this.offsetY >= this.FIX_VP_Y / 2) {\\n              this.lowerRight(index);\\n            }\\n            // ... 其他对角线方向\\n          })\\n        })\\n        .onActionEnd(() => {\\n          this.getUIContext().animateTo({ \\n            curve: curves.interpolatingSpring(0, 1, 400, 38) \\n          }, () => {\\n            this.dragItem = -1;\\n          })\\n        })\\n    )\\n  })\\n}\\n.columnsTemplate(this.curBp === 'md' ? '1fr 1fr 1fr 1fr 1fr' : '1fr 1fr 1fr 1fr')\\n.editMode(true)\\n```\\n\\n**技术要点：**\\n\\n1. **单手势拖拽**：仅使用 `PanGesture`，无需 `LongPressGesture`，实现轻触即拖\\n2. **八方向移动**：支持上下左右及四个对角线方向的移动判断\\n3. **响应式布局**：根据断点（`curBp`）动态调整列数，平板显示 5 列，手机显示 4 列\\n4. **视觉反馈**：拖拽时元素放大（`scale`）并提升层级（`zIndex`）\\n\\n### 场景四：抖动动画（JitterAnimation.ets）\\n\\n抖动动画场景模拟了应用桌面编辑模式。用户长按任意元素后，所有元素进入编辑状态并开始抖动，同时显示删除按钮，点击空白区域退出编辑。\\n\\n![抖动动画](assets/screenshot-jitter.webp)\\n\\n_上图展示了抖动动画场景，长按后元素进入编辑模式，显示删除按钮并伴随抖动效果。_\\n\\n**核心代码：**\\n\\n```typescript\\n// 抖动动画方法\\nprivate jumpWithSpeed(speed: number) {\\n  if (this.isEdit) {\\n    this.rotateZ = -1;\\n    this.getUIContext().animateTo({\\n      delay: 0,\\n      tempo: speed,\\n      duration: 1000,\\n      curve: Curve.Smooth,\\n      playMode: PlayMode.Normal,\\n      iterations: -1  // 无限循环\\n    }, () => {\\n      this.rotateZ = 1;\\n    })\\n  } else {\\n    this.stopJump();\\n  }\\n}\\n\\n// 停止抖动\\nprivate stopJump() {\\n  this.getUIContext().animateTo({\\n    delay: 0,\\n    tempo: 5,\\n    duration: 0,\\n    curve: Curve.Smooth,\\n    playMode: PlayMode.Normal,\\n    iterations: 1\\n  }, () => {\\n    this.rotateZ = 0;\\n  })\\n}\\n\\n// GridItem 旋转动画\\nGridItem() {\\n  Stack({ alignContent: Alignment.TopEnd }) {\\n    Column() {\\n      Image($r(`app.media.space${item}`))\\n        .width(44)\\n        .height(44)\\n        .draggable(false)\\n    }\\n    .width('100%')\\n    .height(73)\\n    .justifyContent(FlexAlign.Center)\\n    .borderRadius(10)\\n    .backgroundColor('#F1F3F5')\\n\\n    // 编辑模式下显示删除按钮\\n    if (this.isEdit) {\\n      Image($r('app.media.close'))\\n        .width(20)\\n        .height(20)\\n        .onClick(() => {\\n          this.getUIContext().animateTo({ duration: 300 }, () => {\\n            this.numbers = this.numbers.filter((element) => element !== item);\\n          })\\n        })\\n    }\\n  }\\n}\\n.rotate({\\n  z: this.rotateZ,\\n  angle: 1,\\n  centerX: '50%',\\n  centerY: '50%'\\n})\\n.gesture(\\n  GestureGroup(GestureMode.Sequence,\\n    LongPressGesture({ repeat: true })\\n      .onAction(() => {\\n        if (!this.isEdit) {\\n          this.isEdit = true;\\n          this.jumpWithSpeed(5);\\n        }\\n      }),\\n    PanGesture({ fingers: 1, direction: null, distance: 0 })\\n      .onActionUpdate((event: GestureEvent) => {\\n        // 拖拽时停止抖动，拖拽结束恢复抖动\\n        this.stopJump();\\n        // ... 拖拽逻辑\\n        this.jumpWithSpeed(5);\\n      })\\n  )\\n)\\n```\\n\\n**技术要点：**\\n\\n1. **`rotate` 属性**：通过改变 `rotateZ` 值实现元素的左右摆动\\n2. **`animateTo` 无限循环**：设置 `iterations: -1` 让抖动动画持续播放\\n3. **编辑状态管理**：`isEdit` 状态变量控制删除按钮的显示/隐藏\\n4. **长按触发**：`LongPressGesture` 触发编辑模式，同时启动抖动动画\\n5. **点击退出**：在 `Scroll` 的 `onClick` 中监听空白区域点击，退出编辑模式\\n\\n## 运行效果\\n\\n以下是四个场景的实际运行截图：\\n\\n| 相同大小拖拽 | 不同大小拖拽 |\\n|:---:|:---:|\\n| ![相同大小拖拽](assets/screenshot-same-drag.webp) | ![不同大小拖拽](assets/screenshot-diff-drag.webp) |\\n\\n| 直接拖拽 | 抖动动画 |\\n|:---:|:---:|\\n| ![直接拖拽](assets/screenshot-direct-drag.webp) | ![抖动动画](assets/screenshot-jitter.webp) |\\n\\n## 总结\\n\\nGridDragSort 项目通过四个典型场景，全面展示了 HarmonyOS `Grid` 组件的拖拽排序能力：\\n\\n1. **`editMode` + `supportAnimation`**：开启 Grid 原生拖拽支持，一行代码实现基础拖拽\\n2. **`GestureGroup` 组合手势**：通过长按+拖拽的组合，实现更精细的交互控制\\n3. **`PanGesture` 单手势**：适用于高频操作场景，减少用户操作步骤\\n4. **`animateTo` 显式动画**：为拖拽过程添加弹性动画和抖动效果，提升交互质感\\n\\n这些技术不仅适用于示例中的场景，也可以灵活应用到相册管理、桌面整理、设备控制等各类网格布局应用中。对于正在学习 HarmonyOS 开发的开发者来说，这是一个深入理解手势交互和动画系统的优质示例项目。\\n\\n## 参考资源\\n\\n- [HarmonyOS Grid 组件官方文档](https://developer.harmonyos.com/cn/docs/documentation/doc-guides-V3/arkts-layout-development-create-grid-0000001504138013-V3)\\n- [HarmonyOS 手势处理官方文档](https://developer.harmonyos.com/cn/docs/documentation/doc-guides-V3/arkts-gesture-0000001504257989-V3)\\n- [HarmonyOS 动画官方文档](https://developer.harmonyos.com/cn/docs/documentation/doc-guides-V3/arkts-animation-0000001504298021-V3)\\n- 项目地址：https://gitcode.com/harmonyos_samples/grid-drag-sort\\n\"}"),r={name:"HarmonyOS 最佳实践/19-GridDragSort — HarmonyOS 网格拖拽场景/19-GridDragSort — HarmonyOS 网格拖拽场景.md"};function E(d,s,g,y,F,c){return l(),p("div",null,[...s[0]||(s[0]=[k("",58)])])}const C=t(r,[["render",E]]);export{m as __pageData,C as default};
